import React, { useMemo, useState } from "react";
import { Link } from "react-router-dom";

/** ----- 타입/라벨 ----- */
type OrderStatus = "PENDING" | "APPROVED" | "SHIPPING" | "RENTING" | "RETURNED" | "CANCELLED";
type Carrier = "우체국" | "CJ대한통운" | "로젠" | "롯데";

const STATUS_LABEL: Record<OrderStatus, string> = {
  PENDING: "접수",
  APPROVED: "승인",
  SHIPPING: "배송중",
  RENTING: "대여중",
  RETURNED: "반납완료",
  CANCELLED: "취소",
};
const STATUS_CLASS: Record<OrderStatus, string> = {
  PENDING: "bg-amber-50 text-amber-700 border-amber-200",
  APPROVED: "bg-sky-50 text-sky-700 border-sky-200",
  SHIPPING: "bg-indigo-50 text-indigo-700 border-indigo-200",
  RENTING: "bg-emerald-50 text-emerald-700 border-emerald-200",
  RETURNED: "bg-gray-100 text-gray-700 border-gray-200",
  CANCELLED: "bg-rose-50 text-rose-700 border-rose-200",
};

type OrderRow = {
  id: string;
  userName: string;
  productName: string;
  variant: string;
  rentalDays: number;
  price: number;
  deposit: number;
  createdAt: string;
  status: OrderStatus;
  carrier?: Carrier;
  invoiceNo?: string;
};

/** ----- 더미 데이터 ----- */
const MOCK: OrderRow[] = [
  { id: "LND-202510-0001", userName: "정다인", productName: "SYND 데몬 덕다운 경량 후드 패딩", variant: "Light Blue / FREE", rentalDays: 3, price: 24000, deposit: 15000, createdAt: "2025-10-03T10:11:00+09:00", status: "PENDING" },
  { id: "LND-202510-0002", userName: "김승윤", productName: "러플 스커트", variant: "Ivory / S", rentalDays: 5, price: 22000, deposit: 15000, createdAt: "2025-10-02T16:30:00+09:00", status: "APPROVED" },
  { id: "LND-202510-0003", userName: "박예진", productName: "SYND 데몬 덕다운 경량 후드 패딩", variant: "Light Blue / FREE", rentalDays: 7, price: 26000, deposit: 15000, createdAt: "2025-10-01T12:05:00+09:00", status: "SHIPPING", carrier: "우체국", invoiceNo: "1234567890" },
  { id: "LND-202509-0099", userName: "홍길동", productName: "새틴 블라우스", variant: "Pink / M", rentalDays: 3, price: 18000, deposit: 10000, createdAt: "2025-09-28T09:10:00+09:00", status: "RENTING" },
  { id: "LND-202509-0098", userName: "이서연", productName: "SYND 데몬 덕다운 경량 후드 패딩", variant: "Light Blue / FREE", rentalDays: 3, price: 24000, deposit: 15000, createdAt: "2025-09-20T14:22:00+09:00", status: "RETURNED" },
];

/** ----- 유틸 ----- */
type SortKey = keyof Pick<OrderRow, "id" | "userName" | "productName" | "createdAt" | "price" | "status">;
const formatKRW = (n: number) => n.toLocaleString("ko-KR") + "원";
const formatDate = (iso: string) => {
  const d = new Date(iso);
  const y = d.getFullYear(); const m = String(d.getMonth()+1).padStart(2,"0"); const day = String(d.getDate()).padStart(2,"0");
  const hh = String(d.getHours()).padStart(2,"0"); const mm = String(d.getMinutes()).padStart(2,"0");
  return `${y}.${m}.${day} ${hh}:${mm}`;
};

/** ===== 메인 컴포넌트 ===== */
export default function AdminOrders() {
  // 검색/정렬/페이지
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<OrderStatus | "ALL">("ALL");
  const [recentDays, setRecentDays] = useState<number>(7);
  const [sortKey, setSortKey] = useState<SortKey>("createdAt");
  const [sortDir, setSortDir] = useState<"asc" | "desc">("desc");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [selected, setSelected] = useState<Set<string>>(new Set());

  // 출고 처리 패널 상태(송장/택배사)
  const [carrier, setCarrier] = useState<Carrier>("우체국");
  const [invoiceNo, setInvoiceNo] = useState("");

  // fetch 대체
  const rows = MOCK;

  // 필터/정렬
  const filtered = useMemo(() => {
    const since = new Date(); since.setDate(since.getDate() - recentDays);
    return rows
      .filter((r) => (status === "ALL" ? true : r.status === status))
      .filter((r) => new Date(r.createdAt) >= since)
      .filter((r) => {
        const q = query.trim().toLowerCase(); if (!q) return true;
        return r.id.toLowerCase().includes(q) || r.userName.toLowerCase().includes(q) || r.productName.toLowerCase().includes(q);
      })
      .sort((a, b) => {
        const av = a[sortKey]; const bv = b[sortKey];
        let cmp = 0;
        if (sortKey === "price") cmp = Number(av) - Number(bv);
        else if (sortKey === "createdAt") cmp = new Date(String(av)).getTime() - new Date(String(bv)).getTime();
        else cmp = String(av).localeCompare(String(bv), "ko");
        return sortDir === "asc" ? cmp : -cmp;
      });
  }, [rows, query, status, recentDays, sortKey, sortDir]);

  // 페이지
  const total = filtered.length;
  const pageCount = Math.max(1, Math.ceil(total / pageSize));
  const current = useMemo(() => {
    const start = (page - 1) * pageSize;
    return filtered.slice(start, start + pageSize);
  }, [filtered, page, pageSize]);

  // 선택
  const toggleAll = (checked: boolean) => checked ? setSelected(new Set(current.map(r => r.id))) : setSelected(new Set());
  const toggleOne = (id: string) => setSelected(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });

  // 정렬
  const changeSort = (key: SortKey) => sortKey === key ? setSortDir(d => d === "asc" ? "desc" : "asc") : (setSortKey(key), setSortDir("asc"));

  // 일괄 처리 (데모)
  const bulk = (action: "approve" | "ship" | "return" | "cancel") => {
    if (!selected.size) return alert("선택된 주문이 없습니다.");
    alert(`[DEMO] ${action} → ${Array.from(selected).join(", ")}`);
    setSelected(new Set());
  };

  // 우측: 주문량 순위(최근 N일 기준)
  const ranking = useMemo(() => {
    const m = new Map<string, number>();
    filtered.forEach(r => {
      const key = `${r.productName} | ${r.variant}`;
      m.set(key, (m.get(key) || 0) + 1);
    });
    return Array.from(m.entries()).sort((a,b)=>b[1]-a[1]).slice(0, 10);
  }, [filtered]);

  // 우측: 예약(라운드) 현황 – 데모
  const preorder = {
    round: 1,
    reserved: 120, // 예약 접수 수량
    produced: 90,  // 생산 완료
    threshold: 150 // 이 값 이상이면 추가발주 권고
  };
  const needRestock = preorder.reserved >= preorder.threshold;

  // 출고 처리(송장 저장) – 데모
  const saveInvoice = () => {
    if (!selected.size) return alert("송장 저장: 주문을 선택하세요.");
    if (!invoiceNo.trim()) return alert("송장번호를 입력하세요.");
    alert(`[DEMO] ${carrier} ${invoiceNo} 저장 → ${Array.from(selected).join(", ")}`);
    setInvoiceNo("");
    setSelected(new Set());
  };

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold">주문/대여 관리</h2>
        <Link to="/admin" className="text-sm underline underline-offset-4 hover:opacity-80">대시보드</Link>
      </div>

      {/* 상단 필터 바 */}
      <div className="grid grid-cols-1 md:grid-cols-[1fr_auto_auto_auto] gap-3">
        <input className="border rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-black/10"
               placeholder="주문번호/이름/상품명 검색"
               value={query} onChange={(e)=>{setQuery(e.target.value); setPage(1);}}/>
        <select className="border rounded-xl px-3 py-2" value={status} onChange={(e)=>{setStatus(e.target.value as any); setPage(1);}}>
          <option value="ALL">상태 전체</option>
          {Object.keys(STATUS_LABEL).map(k => <option key={k} value={k}>{STATUS_LABEL[k as OrderStatus]}</option>)}
        </select>
        <select className="border rounded-xl px-3 py-2" value={recentDays} onChange={(e)=>{setRecentDays(Number(e.target.value)); setPage(1);}}>
          <option value={3}>최근 3일</option><option value={7}>최근 7일</option>
          <option value={14}>최근 14일</option><option value={30}>최근 30일</option>
        </select>
        <select className="border rounded-xl px-3 py-2" value={pageSize} onChange={(e)=>{setPageSize(Number(e.target.value)); setPage(1);}}>
          <option value={10}>10개씩</option><option value={20}>20개씩</option><option value={50}>50개씩</option>
        </select>
      </div>

      {/* 메인 2컬럼: 왼쪽 테이블 / 오른쪽 패널 */}
      <div className="grid grid-cols-1 xl:grid-cols-[1fr_320px] gap-5">
        {/* 왼쪽: 테이블 + 일괄 액션 */}
        <div className="space-y-3">
          <div className="flex flex-wrap gap-2">
            <button className="px-3 py-2 rounded-xl border hover:bg-black/5" onClick={()=>bulk("approve")}>승인</button>
            <button className="px-3 py-2 rounded-xl border hover:bg-black/5" onClick={()=>bulk("ship")}>발송 처리</button>
            <button className="px-3 py-2 rounded-xl border hover:bg-black/5" onClick={()=>bulk("return")}>반납 완료</button>
            <button className="px-3 py-2 rounded-xl border hover:bg-black/5" onClick={()=>bulk("cancel")}>취소</button>
            <span className="text-sm text-gray-500 ml-auto">{filtered.length}건</span>
          </div>

          <div className="border rounded-2xl bg-white overflow-x-auto">
            <table className="min-w-[860px] w-full text-sm">
              <thead className="border-b bg-gray-50">
                <tr>
                  <th className="p-3 w-10">
                    <input type="checkbox"
                           checked={current.length>0 && current.every(r=>selected.has(r.id))}
                           onChange={(e)=>toggleAll(e.target.checked)} />
                  </th>
                  <Th label="주문번호" k="id" sortKey={sortKey} sortDir={sortDir} onSort={changeSort}/>
                  <Th label="고객" k="userName" sortKey={sortKey} sortDir={sortDir} onSort={changeSort}/>
                  <Th label="상품" k="productName" sortKey={sortKey} sortDir={sortDir} onSort={changeSort}/>
                  <th className="p-3 text-left">옵션</th>
                  <th className="p-3 text-right">대여일</th>
                  <Th label="금액" k="price" align="right" sortKey={sortKey} sortDir={sortDir} onSort={changeSort}/>
                  <Th label="주문일" k="createdAt" sortKey={sortKey} sortDir={sortDir} onSort={changeSort}/>
                  <Th label="상태" k="status" sortKey={sortKey} sortDir={sortDir} onSort={changeSort}/>
                  <th className="p-3 text-right w-24">액션</th>
                </tr>
              </thead>
              <tbody>
                {current.map((r)=>(
                  <tr key={r.id} className="border-b last:border-0">
                    <td className="p-3"><input type="checkbox" checked={selected.has(r.id)} onChange={()=>toggleOne(r.id)} /></td>
                    <td className="p-3 font-medium">{r.id}</td>
                    <td className="p-3">{r.userName}</td>
                    <td className="p-3">{r.productName}</td>
                    <td className="p-3 text-gray-500">{r.variant}</td>
                    <td className="p-3 text-right">{r.rentalDays}일</td>
                    <td className="p-3 text-right">{formatKRW(r.price)} <span className="text-gray-400">/ 보증금 {formatKRW(r.deposit)}</span></td>
                    <td className="p-3">{formatDate(r.createdAt)}</td>
                    <td className="p-3">
                      <span className={`inline-block border text-xs px-2 py-1 rounded-lg ${STATUS_CLASS[r.status]}`}>{STATUS_LABEL[r.status]}</span>
                    </td>
                    <td className="p-3 text-right">
                      <button className="text-blue-600 hover:underline text-xs">상세</button>
                    </td>
                  </tr>
                ))}
                {current.length===0 && <tr><td className="p-6 text-center text-gray-500" colSpan={10}>조건에 맞는 주문이 없습니다.</td></tr>}
              </tbody>
            </table>
          </div>

          {/* 페이지네이션 */}
          <div className="flex items-center justify-between">
            <div className="text-sm text-gray-500">페이지 {page}/{pageCount}</div>
            <div className="flex items-center gap-2">
              <button className="px-3 py-2 rounded-xl border disabled:opacity-40" onClick={()=>setPage(1)} disabled={page===1}>« 처음</button>
              <button className="px-3 py-2 rounded-xl border disabled:opacity-40" onClick={()=>setPage(p=>Math.max(1,p-1))} disabled={page===1}>‹ 이전</button>
              <button className="px-3 py-2 rounded-xl border disabled:opacity-40" onClick={()=>setPage(p=>Math.min(pageCount,p+1))} disabled={page===pageCount}>다음 ›</button>
              <button className="px-3 py-2 rounded-xl border disabled:opacity-40" onClick={()=>setPage(pageCount)} disabled={page===pageCount}>마지막 »</button>
            </div>
          </div>
        </div>

        {/* 오른쪽: 운영 패널 */}
        <aside className="space-y-4">
          {/* 1) 주문량 순위 */}
          <div className="border rounded-2xl bg-white p-4">
            <h3 className="font-semibold mb-3">주문량 순위 (최근 {recentDays}일)</h3>
            <ol className="space-y-2 text-sm">
              {ranking.map(([k,count], idx)=>(
                <li key={k} className="flex items-center gap-2">
                  <span className="w-6 text-right">{idx+1}.</span>
                  <span className="flex-1 truncate" title={k}>{k}</span>
                  <span className="text-gray-500">{count}건</span>
                </li>
              ))}
              {ranking.length===0 && <p className="text-gray-500">데이터 없음</p>}
            </ol>
          </div>

          {/* 2) 예약 물량/추가 발주 알림 */}
          <div className={`border rounded-2xl p-4 ${needRestock ? "bg-rose-50 border-rose-200" : "bg-white"}`}>
            <h3 className="font-semibold mb-1">예약(라운드) 현황</h3>
            <p className="text-sm text-gray-600 mb-3">1차 예약물량이 빠르게 소진 중입니다.</p>
            <dl className="grid grid-cols-3 text-center text-sm">
              <div><dt className="text-gray-500">라운드</dt><dd className="font-semibold">{preorder.round}차</dd></div>
              <div><dt className="text-gray-500">예약</dt><dd className="font-semibold">{preorder.reserved}건</dd></div>
              <div><dt className="text-gray-500">생산완료</dt><dd className="font-semibold">{preorder.produced}건</dd></div>
            </dl>
            {needRestock ? (
              <div className="mt-3 text-sm">
                <p className="mb-2">⚠️ 1차 예약물량 소진 임박. <b>추가 발주</b>가 필요합니다.</p>
                <button className="px-3 py-2 rounded-xl bg-black text-white w-full">추가발주 요청 생성</button>
              </div>
            ) : (
              <p className="mt-3 text-sm text-gray-500">임계치 미도달 (권고치 {preorder.threshold}건)</p>
            )}
          </div>

          {/* 3) 출고 처리(송장 저장) */}
          <div className="border rounded-2xl bg-white p-4">
            <h3 className="font-semibold mb-3">출고 처리</h3>
            <div className="space-y-2 text-sm">
              <select className="w-full border rounded-xl px-3 py-2" value={carrier} onChange={(e)=>setCarrier(e.target.value as Carrier)}>
                <option>우체국</option><option>CJ대한통운</option><option>로젠</option><option>롯데</option>
              </select>
              <input className="w-full border rounded-xl px-3 py-2" placeholder="송장번호 입력" value={invoiceNo} onChange={(e)=>setInvoiceNo(e.target.value)}/>
              <button className="w-full px-3 py-2 rounded-xl border hover:bg-black/5" onClick={saveInvoice}>송장번호 저장</button>
              <p className="text-xs text-gray-500">선택된 주문 {selected.size}건에 적용됩니다.</p>
            </div>
          </div>

          {/* 4) 채널 하이라이트(알림/후기 인용) – 데모 */}
          <div className="border rounded-2xl bg-white p-4">
            <h3 className="font-semibold mb-2">채널 하이라이트</h3>
            <blockquote className="text-sm bg-gray-50 rounded-xl p-3 leading-relaxed">
              “데몬패딩 주문량 무엇 🐵 … 1차 예약 물량 다 만들어지기 전에 <b>추가발주</b> 넣어야 할 판이에요. 너무 감사합니다 세잉이들 💗”
            </blockquote>
            <p className="mt-2 text-xs text-gray-500">인스타/톡 등 외부 채널 핫 이슈를 요약 표시</p>
          </div>
        </aside>
      </div>
    </div>
  );
}

/** ----- 테이블 헤더(정렬) ----- */
function Th({ label, k, align="left", sortKey, sortDir, onSort }:{
  label:string; k:SortKey; align?:"left"|"right";
  sortKey:SortKey; sortDir:"asc"|"desc"; onSort:(k:SortKey)=>void;
}) {
  const active = sortKey === k;
  return (
    <th className={`p-3 text-${align} select-none`}>
      <button className="inline-flex items-center gap-1 hover:underline" onClick={()=>onSort(k)} title="정렬">
        {label} <span className={active ? "opacity-80" : "opacity-30"}>{active ? (sortDir==="asc"?"↑":"↓") : "↕"}</span>
      </button>
    </th>
  );
}
